def test_defs_is_exactly_the_union_of_the_registered_lanes() -> None:
    assert isinstance(defs, dg.Definitions); lanes = lane_definitions(); assert set(lanes) == set(LANE_MODULES)
    def names(definitions: dg.Definitions, attribute: str) -> set[str]: return {item.name for item in getattr(definitions, attribute) or ()}
    for attribute in ("jobs", "schedules", "sensors"): declared = set().union(*(names(lane, attribute) for lane in lanes.values())); assert names(defs, attribute) == declared, f"root {attribute} != union of lane {attribute}"
    assert names(defs, "jobs"), "the lanes declare no job at all"; assert CORE_STRATEGY_FIXTURE_CANARY_JOB_NAME not in names(defs, "jobs"); defs.get_repository_def()
def test_every_lane_module_is_registered() -> None: from pathlib import Path; package = Path(capture.__file__).parent; on_disk = {f"data_engine.lanes.{path.stem}" for path in package.glob("*.py") if path.stem != "__init__"}; assert on_disk == set(LANE_MODULES), ( f'lane modules on disk {sorted(on_disk)} != registered {sorted(LANE_MODULES)}; add the module to data_engine.lanes.LANE_MODULES or delete it' )
IMPORTED_NOT_OWNED: dict[str, set[str]] = {"data_engine.lanes.triggers": {"jobs"}}
def test_every_definition_a_lane_module_declares_is_in_its_defs() -> None:
    kinds = {"jobs": dg.JobDefinition, "schedules": dg.ScheduleDefinition, "sensors": dg.SensorDefinition}
    for module_name, lane in lane_definitions().items():
        module = __import__(module_name, fromlist=["defs"])
        for attribute, kind in kinds.items():
            if attribute in IMPORTED_NOT_OWNED.get(module_name, set()): continue
            built = {value.name for value in vars(module).values() if isinstance(value, kind)}; listed = {item.name for item in getattr(lane, attribute) or ()}; missing = built - listed; assert not missing, f"{module_name} builds {attribute} {sorted(missing)} but its defs omit them"
