def test_the_two_environments_never_tick_at_the_same_instant() -> None:
    production = tick_cron("topt", "production"); staging = tick_cron("topt", "staging"); assert production != staging, "same-instant crons re-create the per-minute collision"
    for cron in (production, staging): minute, hour, dom, month, dow = cron.split(); assert (hour, dom, month, dow) == ("22", "*", "*", "*"); assert 0 <= int(minute) <= 59
    assert abs(int(production.split()[0]) - int(staging.split()[0])) >= 30; assert tick_cron("topt", "prod") == production; assert tick_cron("topt", "PRODUCTION") == production; assert tick_cron("topt", "dev") == staging, "unrecognized envs share the lower-stakes slot"
