    from data_engine.lanes import triggers; sensor_targets = {job.name for job in triggers.pipeline_trigger_sensor.jobs}
    for tick in capture.TICKS:
        job = defs.get_job_def(tick.job_name); assert {node.name for node in job.graph.node_defs} == {tick.op_name}, tick.key
        if tick.cron is not None: schedule = defs.get_schedule_def(tick.schedule_name); assert schedule.cron_schedule == tick.cron and schedule.job.name == tick.job_name
